htmlform.script:
jq(document).ready(function() {
// Collapse all sections on load
jq(".collapsible-content").hide();

// Toggle content when header is tapped
jq(".sectionHeader").click(function() {
jq(this).toggleClass("expanded");
jq(this).next(".collapsible-content").slideToggle("fast");
});

var HISTORY_SELECTOR = '.order-field-widget.order-clinicalHistory textarea';
var MAX_HISTORY_LENGTH = 500;
var ADDITIONAL_INFO_SELECTOR = '.order-field-widget.order-orderReasonNonCoded textarea';
// Saved in the order's non-coded reason, which holds at most 255 characters
var MAX_ADDITIONAL_INFO_LENGTH = 255;
// From this many characters left, the counter warns that the limit is close
var HISTORY_WARNING_LEFT = 50;

// Clinical history shared with the other tests while a "same clinical history" box is ticked, else null
var sharedHistory = null;

// The order widget clones a hidden template (id ending in "_template") for each test that is added
var isTemplate = function(element) {
var orderForm = jq(element).closest('[id*="_template"]');
return orderForm.length > 0 && /_template$/.test(orderForm.attr('id'));
};

var getOrderForm = function(element) {
return jq(element).closest('[id*="_template"]');
};

var getHistoryFields = function() {
return jq(HISTORY_SELECTOR).filter(function() { return !isTemplate(this); });
};

var getAdditionalInfoFields = function() {
return jq(ADDITIONAL_INFO_SELECTOR).filter(function() { return !isTemplate(this); });
};

// Fill the shared history into the other tests, unless the doctor already typed something different there
var applySharedHistory = function(previousValue) {
if (sharedHistory === null) {
return;
}
getHistoryFields().each(function() {
var field = jq(this);
var current = jq.trim(field.val());
if (current === '' || (previousValue !== undefined && current === jq.trim(previousValue))) {
field.val(sharedHistory);
}
});
};

// The nearest other test with a clinical history: the closest one above, otherwise the closest one below
var findHistoryToCopy = function(field) {
var fields = getHistoryFields().toArray();
var index = fields.indexOf(field[0]);
for (var i = index - 1; i >= 0; i--) {
if (jq.trim(jq(fields[i]).val()) !== '') {
return jq(fields[i]);
}
}
for (var j = index + 1; j < fields.length; j++) {
if (jq.trim(jq(fields[j]).val()) !== '') {
return jq(fields[j]);
}
}
return null;
};

// Text is only changed when it differs, as every change to the page wakes the observer below, which would
// otherwise run again without end
var setText = function(element, text) {
if (element.text() !== text) {
element.text(text);
}
};

// Each modality (X-Ray, CT Scan, ...) is its own section of the form
var getModality = function(field) {
return jq(field).closest('.section');
};

var getModalityName = function(section) {
return jq.trim(section.find('.sectionHeader').first().text());
};

// The clinical history boxes of all the tests in the same modality as this one
var getModalityHistoryFields = function(field) {
var section = getModality(field)[0];
return getHistoryFields().filter(function() { return getModality(this)[0] === section; });
};

// The clinical histories of one modality share one limit. A history repeated in several tests
// (similar clinical history) is counted once; each different history adds its own characters.
var countModalityCharacters = function(fields) {
var seen = {};
var total = 0;
jq(fields).each(function() {
var value = jq(this).val();
if (jq.trim(value) !== '' && !seen['#' + value]) {
seen['#' + value] = true;
total += value.length;
}
});
return total;
};

// Whether the other test's history changes along with this one when this one is edited (see the input
// handler below): it copied this one, or this one is shared and the other still holds the shared text
var followsField = function(other, field, previousValue) {
var copiedFrom = other.data('copiedFrom');
if (copiedFrom && copiedFrom[0] === field[0] && other.val() === other.data('copiedText')) {
return true;
}
var checkbox = field.data('sameHistoryCheckbox');
return !!checkbox && checkbox.is(':checked') && !field.data('copiedFrom') && sharedHistory !== null
&& jq.trim(other.val()) === jq.trim(previousValue || '');
};

// The other tests of the same modality whose histories count against this one's room
var getOtherModalityHistories = function(field, previousValue) {
return getModalityHistoryFields(field).filter(function() {
return this !== field[0] && !followsField(jq(this), field, previousValue);
});
};

// Keeps a clinical history within what its modality has left. Text identical to another test's history
// adds nothing, and text already there is never cut, only stopped from growing.
var limitHistoryText = function(field, previousValue) {
cleanHistoryText(field[0], MAX_HISTORY_LENGTH);
var others = getOtherModalityHistories(field, previousValue);
var value = field.val();
var isSame = others.filter(function() { return jq(this).val() === value; }).length > 0;
if (!isSame) {
var room = Math.max(MAX_HISTORY_LENGTH - countModalityCharacters(others), (previousValue || '').length);
if (value.length > room) {
cleanHistoryText(field[0], room);
}
}
};

var showCounter = function(field, used, maxLength, scope) {
var counter = field.data('historyCounter');
var left = maxLength - used;
var hint = 'Up to ' + maxLength + ' characters' + scope;
if (left < 0) {
hint = 'Over the limit by ' + (-left) + (left === -1 ? ' character' : ' characters') + scope;
}
else if (left === 0) {
hint = 'Limit reached' + scope + ': no more text can be added';
}
else if (left <= HISTORY_WARNING_LEFT) {
hint = left + (left === 1 ? ' character' : ' characters') + ' left' + scope;
}
setText(counter.find('.history-counter-hint'), hint);
setText(counter.find('.history-counter-count'), used + ' / ' + maxLength);
counter.toggleClass('history-counter-near', left > 0 && left <= HISTORY_WARNING_LEFT);
counter.toggleClass('history-counter-full', left <= 0);
field.toggleClass('history-field-full', left <= 0);
};

// Show how many characters are used and warn as the limit gets close: for each additional information on
// its own, and for the clinical histories, all the tests of the modality together
var updateHistoryCounters = function() {
getAdditionalInfoFields().each(function() {
var field = jq(this);
if (field.data('historyCounter')) {
showCounter(field, field.val().length, field.data('maxLength'), '');
}
});
getHistoryFields().each(function() {
var field = jq(this);
if (!field.data('historyCounter')) {
return;
}
var value = field.val();
field.data('lastValue', value);
var used = countModalityCharacters(getModalityHistoryFields(field));
showCounter(field, used, MAX_HISTORY_LENGTH, ' for all ' + getModalityName(getModality(field)));
// The browser stops typing once the modality has no room left for this test
var others = getOtherModalityHistories(field, value);
var room = Math.max(MAX_HISTORY_LENGTH - countModalityCharacters(others), value.length);
if (field.attr('maxlength') !== String(room)) {
field.attr('maxlength', room);
}
});
};

// Text is kept on one line, and never longer than the limit, even if the browser lets more through:
// line breaks in pasted text become spaces
var cleanHistoryText = function(textarea, maxLength) {
var value = textarea.value;
var cleaned = value.replace(/[\r\n]+/g, ' ');
if (cleaned.length > maxLength) {
cleaned = cleaned.substring(0, maxLength);
}
if (cleaned !== value) {
var caret = Math.min(textarea.selectionStart || cleaned.length, cleaned.length);
textarea.value = cleaned;
textarea.setSelectionRange(caret, caret);
}
};

// Limits the text to one line and the given length, with a counter just below the box
var addCharacterLimit = function(field, maxLength) {
// The browser stops typing and pasting beyond the limit
field.attr('maxlength', maxLength).addClass('history-field');
field.data('maxLength', maxLength);
var counter = jq('<div class="history-counter"><span class="history-counter-hint"></span>'
+ '<span class="history-counter-count"></span></div>');
field.after(counter);
field.data('historyCounter', counter);

// The Enter key does not start a new line
field.on('keydown', function(e) {
if (e.key === 'Enter' || e.keyCode === 13) {
e.preventDefault();
}
});
return counter;
};

var addAdditionalInfoLimit = function(textarea) {
var field = jq(textarea);
if (field.data('additionalInfoReady')) {
return false;
}
field.data('additionalInfoReady', true);
addCharacterLimit(field, MAX_ADDITIONAL_INFO_LENGTH);
field.on('input', function() {
cleanHistoryText(this, MAX_ADDITIONAL_INFO_LENGTH);
updateHistoryCounters();
});
return true;
};

var addSameHistoryCheckbox = function(textarea) {
var field = jq(textarea);
if (field.data('sameHistoryReady')) {
return false;
}
field.data('sameHistoryReady', true);

var counter = addCharacterLimit(field, MAX_HISTORY_LENGTH);

var checkbox = jq('<input type="checkbox" class="same-history-checkbox"/>');
var wrapper = jq('<label class="same-history-option"></label>')
.append(checkbox)
.append(' Similar clinical history');
counter.after(wrapper);
field.data('sameHistoryCheckbox', checkbox);

checkbox.change(function() {
if (this.checked) {
if (jq.trim(field.val()) === '') {
// Empty test: copy the history from another test, and follow it while ticked
var source = findHistoryToCopy(field);
if (source === null) {
alert('Enter the clinical history in one of the tests first.');
this.checked = false;
return;
}
field.val(source.val());
field.data('copiedFrom', source);
field.data('copiedText', source.val());
}
else {
// Test with a history: share it with all the other tests that are still empty
jq('.same-history-checkbox').not(this).filter(function() {
return !jq(this).closest('.order-field-widget').find('textarea').data('copiedFrom');
}).prop('checked', false);
sharedHistory = field.val();
applySharedHistory();
}
}
else {
if (field.data('copiedFrom')) {
// Remove the copied text, unless the doctor has changed it since
if (field.val() === field.data('copiedText')) {
field.val('');
}
field.removeData('copiedFrom');
field.removeData('copiedText');
}
else {
sharedHistory = null;
}
}
updateHistoryCounters();
});

field.on('input', function() {
limitHistoryText(field, field.data('lastValue'));
// Keep the other tests in step while the source text is edited
if (checkbox.is(':checked') && !field.data('copiedFrom')) {
var previous = sharedHistory;
sharedHistory = field.val();
applySharedHistory(previous);
}
// Update tests that copied from this one and have not been changed since
getHistoryFields().each(function() {
var other = jq(this);
var copiedFrom = other.data('copiedFrom');
if (copiedFrom && copiedFrom[0] === field[0] && other.val() === other.data('copiedText')) {
other.val(field.val());
other.data('copiedText', field.val());
}
});
getModalityHistoryFields(field).closest('.order-field-widget').find('.clinical-history-error').remove();
updateHistoryCounters();
});

// A test added after a history was shared starts with that history
if (sharedHistory !== null && jq.trim(field.val()) === '') {
field.val(sharedHistory);
}
return true;
};

// Only does something when a test was added, so changes the script itself makes to the page are ignored
var decorateHistoryFields = function() {
var added = false;
getHistoryFields().each(function() {
added = addSameHistoryCheckbox(this) || added;
});
getAdditionalInfoFields().each(function() {
added = addAdditionalInfoLimit(this) || added;
});
if (added) {
updateHistoryCounters();
}
};

decorateHistoryFields();
// Tests are added to the page by the order widget when the doctor clicks to add one
if (window.MutationObserver) {
new MutationObserver(decorateHistoryFields).observe(document.body, { childList: true, subtree: true });
}

// Clinical history is required for every test being ordered, and the histories of one modality together
// cannot be longer than the limit (a similar history counts once)
var validateClinicalHistory = function() {
var missing = [];
var tooLong = false;
var modalities = [];
getHistoryFields().each(function() {
var field = jq(this);
var orderForm = getOrderForm(field);
var concept = orderForm.find('.order-field-widget.order-concept select').val();
var action = orderForm.find('.order-field.order-action select').val();
var widget = field.closest('.order-field-widget');
widget.find('.clinical-history-error').remove();
if (!concept || action === 'DISCONTINUE') {
return;
}
if (jq.trim(field.val()) === '') {
widget.append('<span class="error clinical-history-error">Clinical history is required</span>');
missing.push(field);
return;
}
var section = getModality(field)[0];
var modality = jq.grep(modalities, function(m) { return m.section === section; })[0];
if (!modality) {
modality = { section: section, fields: [] };
modalities.push(modality);
}
modality.fields.push(field[0]);
});
jq.each(modalities, function(i, modality) {
var total = countModalityCharacters(modality.fields);
if (total > MAX_HISTORY_LENGTH) {
var name = getModalityName(jq(modality.section));
jq(modality.fields).closest('.order-field-widget').append('<span class="error clinical-history-error">'
+ 'The clinical histories for ' + name + ' add up to ' + total + ' characters; together they '
+ 'cannot be longer than ' + MAX_HISTORY_LENGTH + ' characters</span>');
missing.push(jq(modality.fields[0]));
tooLong = true;
}
});
if (missing.length > 0) {
// Open the section holding the first missing field so the doctor can see it
var content = missing[0].closest('.collapsible-content');
if (!content.is(':visible')) {
content.prev('.sectionHeader').addClass('expanded');
content.show();
}
missing[0].focus();
alert(tooLong ? 'Clinical history must be filled in for every test, and the clinical histories of one '
+ 'type of study (X-Ray, CT Scan, ...) together cannot be longer than ' + MAX_HISTORY_LENGTH
+ ' characters. A similar clinical history is only counted once.'
: 'Clinical history is required for every test ordered.');
return false;
}
return true;
};

if (typeof htmlForm !== 'undefined' && htmlForm.getBeforeSubmit) {
htmlForm.getBeforeSubmit().push(validateClinicalHistory);
}
else if (typeof beforeSubmit !== 'undefined') {
beforeSubmit.push(validateClinicalHistory);
}
});
